<?php include "../includes/cek_session.php";include "../config/koneksi.php";$title="Riwayat Transaksi";include "../includes/header.php";$data=mysqli_query($koneksi,"SELECT t.*,u.nama_lengkap,COALESCE(p.nama_pelanggan,'Pelanggan Umum') pelanggan FROM tb_transaksi t JOIN tb_pengguna u ON u.id_pengguna=t.id_pengguna LEFT JOIN tb_pelanggan p ON p.id_pelanggan=t.id_pelanggan ORDER BY t.id_transaksi DESC");?>
<div class="page-head"><h1>Riwayat Transaksi</h1></div><div class="panel"><div class="table-wrap"><table><tr><th>No Transaksi</th><th>Tanggal</th><th>Kasir</th><th>Pelanggan</th><th>Total</th><th>Aksi</th></tr><?php while($t=mysqli_fetch_assoc($data)):?><tr><td><?=htmlspecialchars($t['no_transaksi'])?></td><td><?=htmlspecialchars($t['tanggal'])?></td><td><?=htmlspecialchars($t['nama_lengkap'])?></td><td><?=htmlspecialchars($t['pelanggan'])?></td><td>Rp <?=number_format($t['total_bayar'],0,',','.')?></td><td><a class="btn" href="detail.php?id=<?=$t['id_transaksi']?>">Detail</a></td></tr><?php endwhile;?></table></div></div><?php include "../includes/footer.php";?>